send_batch_emails.beforeRequest:
if (!inputs.idempotency_key) delete request.headers['Idempotency-Key'];
request.body = request.body.map((e) => {
  const p = {from: e.from, to: e.to, subject: e.subject};
  p[e.content_type === 'html' ? 'html' : 'text'] = e.content;
  ['reply_to', 'cc', 'bcc'].forEach((k) => { if (e[k]) p[k] = e[k]; });
  return p;
});
return request;

update_broadcast.beforeRequest:
if (inputs.content && !inputs.content_type) throw new Error('Content Type is required when Content is provided.');
if (inputs.content_type && !inputs.content) throw new Error('Content is required when Content Type is provided.');
if (inputs.content_type === 'html') request.body.html = inputs.content;
else if (inputs.content_type === 'text') request.body.text = inputs.content;
if (Object.keys(request.body).length === 0) throw new Error('At least one field must be provided to update the broadcast.');
return request;

create_contact_property.beforeRequest:
if (inputs.type === 'number' && inputs.fallback_value) {
  const n = Number(inputs.fallback_value);
  if (!Number.isFinite(n)) throw new Error('Fallback Value must be a valid number, got "' + inputs.fallback_value + '".');
  request.body.fallback_value = n;
}
return request;
